namespace StarRacingPrototype {
 // Production PhysX/CCD8 fixtures; no Player build and no audio device output.
 [InitializeOnLoad] public static class PhysicalContactChecks {
  const string Key="StarRacing.PhysicalContacts";
  static int startup,failures,assertions;static string Output=>Environment.GetEnvironmentVariable("STAR_RACING_PHYSICAL_CONTACT_QA_DIR");
  static bool Measure=>Environment.GetEnvironmentVariable("STAR_RACING_PHYSICAL_CONTACT_MEASURE")=="1";
  static readonly MethodInfo Tick=typeof(MagneticVehicle).GetMethod("FixedUpdate",BindingFlags.Instance|BindingFlags.NonPublic);
  static PhysicalContactChecks(){EditorApplication.playModeStateChanged+=Changed;}
  const string ProfilePath="Assets/StarRacing/Resources/Vehicle/CloudlineContactProfile.json";
  static string ModelHash(){using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes("Assets/StarRacing/Resources/Vehicle/Cloudline.fbx"))).Replace("-","").ToLowerInvariant();}
  public static void BakeContactProfile(){var root=new GameObject("contact profile bake");try{var visual=StaticVehicleVisual.Create(root.transform,Color.cyan,true);File.WriteAllText(ProfilePath,JsonUtility.ToJson(visual.MeasureProfileDocument(root.transform,ModelHash()),true)+"\n");AssetDatabase.ImportAsset(ProfilePath);Debug.Log("CONTACT_PROFILE_BAKED "+ProfilePath);}finally{UnityEngine.Object.DestroyImmediate(root);}}
  public static void CheckBakedProfile(){var root=new GameObject("contact profile equality");try{var visual=StaticVehicleVisual.Create(root.transform,Color.cyan,true);var actual=visual.ContactProfile();var expected=visual.MeasureProfileDocument(root.transform,ModelHash());var saved=JsonUtility.FromJson<StaticVehicleVisual.ProfileDocument>(File.ReadAllText(ProfilePath));if(saved.modelSha256!=expected.modelSha256||((ModelImporter)AssetImporter.GetAtPath("Assets/StarRacing/Resources/Vehicle/Cloudline.fbx")).isReadable)throw new Exception("Contact profile provenance/readability changed");for(int i=0;i<5;i++)if((actual[i].center-expected.sections[i].center).magnitude>1e-5f||(actual[i].size-expected.sections[i].size).magnitude>1e-5f)throw new Exception("Stale baked contact geometry section="+i);Debug.Log("CONTACT_PROFILE_EQUALITY_OK sections=5 tolerance=1e-5 modelSha256="+saved.modelSha256+" runtimeReadWrite=false");}finally{UnityEngine.Object.DestroyImmediate(root);}}
  public static void RunVisual(){Run();SessionState.SetBool(Key+"Visual",true);}
  public static void RunAdjacent(){
   Directory.CreateDirectory(Output);CheckBakedProfile();StrideVisualChecks.Run();CloudlineVehicleChecks.Run();VehicleAudioChecks.Run();
   RecoveryGhostChecks.Run();AirSteeringChecks.Run();GravityChecks.Run();RoadSmoothnessChecks.Run();SilentStartupChecks.Run();
   File.WriteAllText(Path.Combine(Output,"result.txt"),"PHYSICAL_ADJACENT_OK visuals driveFeedback offlineAudio recovery airSteering gravity loop silentStartup\n");
  }
  public static void Run(){Directory.CreateDirectory(Output);SessionState.SetBool(Key,true);SessionState.SetBool(Key+"Failed",false);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);startup=0;EditorApplication.update+=Enter;}
  static void Enter(){if(++startup<15)return;EditorApplication.update-=Enter;EditorApplication.isPlaying=true;}
  static void Changed(PlayModeStateChange state){if(!SessionState.GetBool(Key,false))return;if(state==PlayModeStateChange.EnteredPlayMode){startup=0;EditorApplication.update+=Execute;}if(state==PlayModeStateChange.EnteredEditMode){SessionState.SetBool(Key,false);EditorApplication.Exit(SessionState.GetBool(Key+"Failed",false)?1:0);}}
  static void Require(bool ok,string reason){assertions++;if(!ok){failures++;Log("FAIL "+reason);}}
  static void Log(string value){Debug.Log(value);File.AppendAllText(Path.Combine(Output,"metrics.txt"),value+"\n");}
  static void Execute(){if(++startup<15)return;EditorApplication.update-=Execute;var mode=Physics.simulationMode;float dt=Time.fixedDeltaTime;failures=assertions=0;
   var observerRoot=new GameObject("physical native observer");nativeHistory.Clear();nativeHistogram.Clear();RoadNativeContactObserver.Begin(observerRoot);
   try{Physics.simulationMode=SimulationMode.Script;Time.fixedDeltaTime=.01f;if(SessionState.GetBool(Key+"Visual",false)){VisualProof();return;}if(Environment.GetEnvironmentVariable("STAR_RACING_PHYSICAL_RAMP_ONLY")=="1"){Ramp(-1,0,42);Ramp(1,0,42);return;}Audit();AngularCcd();foreach(float side in new[]{-1f,1f})foreach(float angle in new[]{0f,15f,30f,45f})foreach(float speed in new[]{42f,138.8889f})Ramp(side,angle,speed);foreach(float side in new[]{-1f,1f})foreach(float speed in new[]{42f,138.8889f})Ramp(side,15f,speed,true);foreach(float side in new[]{-1f,1f})RampSide(side);CompoundGhost();SolidPolicy();foreach(float side in new[]{-1f,1f})Escape(side);foreach(float speed in new[]{42f,138.8889f})foreach(float angle in new[]{0f,30f,60f})Wall(speed,angle);}
   catch(Exception e){failures++;File.WriteAllText(Path.Combine(Output,"failure.txt"),e.ToString());Debug.LogException(e);}
   finally{RoadNativeContactObserver.End();UnityEngine.Object.DestroyImmediate(observerRoot);Log("NATIVE_STEPS_HISTOGRAM "+string.Join(",",nativeHistogram.Select(p=>p.Key+":"+p.Value)));SessionState.SetBool(Key+"Visual",false);Physics.simulationMode=mode;Time.fixedDeltaTime=dt;File.WriteAllText(Path.Combine(Output,"result.txt"),$"PHYSICAL_CONTACT_{(Measure?"MEASURED":failures==0?"OK":"FAILED")} assertions={assertions} failures={failures}\n");SessionState.SetBool(Key+"Failed",!Measure&&failures>0);EditorApplication.isPlaying=false;}
  }
  static TrackBuilder Road(GameObject root){var go=new GameObject("physical road");go.transform.SetParent(root.transform);var track=go.AddComponent<TrackBuilder>();track.Build(new TrackRoute(RoadVolumeChecks.FlatRoad()));return track;}
  static MagneticVehicle Car(GameObject root,TrackBuilder track,int id,float distance,float lane,float speed,float yaw=0){var go=new GameObject("physical car "+id);go.transform.SetParent(root.transform);var car=go.AddComponent<MagneticVehicle>();car.Initialize(track,id,Color.cyan,ReleaseBalance.Parse(Resources.Load<TextAsset>("balance-config").text),true);car.enabled=false;car.ResetAt(distance,lane);car.Body.rotation=car.Frame.Rotation*Quaternion.Euler(0,yaw,0);car.Body.linearVelocity=car.Body.rotation*Vector3.forward*speed;go.transform.SetPositionAndRotation(car.Body.position,car.Body.rotation);return car;}
  static readonly System.Collections.Generic.Queue<string> nativeHistory=new System.Collections.Generic.Queue<string>();
  static readonly System.Collections.Generic.SortedDictionary<long,int> nativeHistogram=new System.Collections.Generic.SortedDictionary<long,int>();
  static bool Finite(Vector3 value)=>float.IsFinite(value.x)&&float.IsFinite(value.y)&&float.IsFinite(value.z);
  static void Step(MagneticVehicle[] cars,int tick,Action sample=null){foreach(var car in cars){car.SetRaceContext(true,1,cars.Length,tick*.01);car.Hold(false);car.PrepareProjection();Tick.Invoke(car,null);}long before=RacePhysicsStepper.NativeSteps;RacePhysicsStepper.SimulatePrepared(cars,.01f,8,()=>{
   RoadNativeContactObserver.AfterStep();
   foreach(var car in cars){
    if(Environment.GetEnvironmentVariable("STAR_RACING_ROAD_OBSERVER")=="1") {
     string row="NATIVE_PHYSICAL tick="+tick+" step="+RacePhysicsStepper.NativeSteps+" pose="+car.Body.position.ToString("G9")+" velocity="+car.Body.linearVelocity.ToString("G9")+" angular="+car.Body.angularVelocity.ToString("G9");foreach(var box in car.ContactColliders)row+=RoadNativeContactObserver.For(box);nativeHistory.Enqueue(row);while(nativeHistory.Count>8)nativeHistory.Dequeue();
    }
    if(!Finite(car.Body.position)||!Finite(car.Body.linearVelocity)||!Finite(car.Body.angularVelocity)){foreach(var row in nativeHistory)Log(row);throw new Exception("Nonfinite native PhysX state at tick="+tick+" step="+RacePhysicsStepper.NativeSteps);}
   }
   sample?.Invoke();
  });long steps=RacePhysicsStepper.NativeSteps-before;nativeHistogram.TryGetValue(steps,out int total);nativeHistogram[steps]=total+1;}
  static void Audit(){var root=new GameObject("physical envelope audit");try{var track=Road(root);var car=Car(root,track,0,70,0,0);var visual=car.GetComponentInChildren<StaticVehicleVisual>();var box=car.GetComponent<BoxCollider>();Log($"ENVELOPE visual={visual.LocalBounds} chassis={box.center}/{box.size}");
   var points=visual.GetComponentsInChildren<MeshFilter>().Where(f=>!f.name.StartsWith("Exhaust plume")).SelectMany(f=>f.sharedMesh.vertices.Select(v=>car.transform.InverseTransformPoint(f.transform.TransformPoint(v)))).ToArray();
   for(int i=0;i<7;i++){float a=-2.1f+i*.6f,b=a+.6f;var p=points.Where(v=>v.z>=a&&v.z<=b).ToArray();if(p.Length>0)Log($"PROFILE z={a:F3}..{b:F3} x={p.Min(v=>v.x):F4}..{p.Max(v=>v.x):F4} y={p.Min(v=>v.y):F4}..{p.Max(v=>v.y):F4}");}
   Require(Mathf.Abs(Physics.defaultContactOffset-.01f)<.000001f,"road offset changed; review certified contact plane band");Require(car.ContactColliders.All(c=>c.contactOffset==.005f),"body skin changed");Require(box.size.x<=visual.LocalBounds.size.x+.06f,"collision width exceeds visible model");Require(box.size.y<=visual.LocalBounds.size.y+.06f,"collision height exceeds visible model");
  }finally{UnityEngine.Object.DestroyImmediate(root);}}
  static bool ResolutionActive(MagneticVehicle car)=>(bool)typeof(MagneticVehicle).GetField("impactResolutionActive",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(car);
  static float NativeResolution(MagneticVehicle car){float slice=(float)typeof(MagneticVehicle).GetMethod("LimitNativeStep",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(car,new object[]{.00125f});typeof(MagneticVehicle).GetMethod("AdvanceImpactResolution",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(car,new object[]{.00125f,.00125f});return slice;}
  static void ArmAngularCcd(MagneticVehicle car){var omega=car.Body.angularVelocity;car.Body.angularVelocity=Vector3.up*12;typeof(MagneticVehicle).GetField("pendingAngularImpact",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(car,true);float slice=NativeResolution(car);car.Body.angularVelocity=omega;Require(ResolutionActive(car)&&slice<.00125f&&car.Body.collisionDetectionMode==CollisionDetectionMode.ContinuousDynamic,"strong angular impact lacked temporal resolution");}
  static void AngularCcd(){var root=new GameObject("angular impact lifecycle");try{var track=Road(root);var car=Car(root,track,0,70,0,0);car.Body.angularVelocity=Vector3.up*12;Require(NativeResolution(car)==.00125f&&!ResolutionActive(car),"ordinary rotation refined without contact");car.Body.angularVelocity=Vector3.zero;ArmAngularCcd(car);for(int i=0;i<157;i++)NativeResolution(car);Require(ResolutionActive(car),"impact resolution lost minimum hold");for(int i=0;i<14;i++)NativeResolution(car);Require(!ResolutionActive(car),"quiet impact resolution did not end");ArmAngularCcd(car);typeof(MagneticVehicle).GetMethod("BeginGhosting",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(car,null);Require(ResolutionActive(car),"ghost removed angular road protection");car.ResetAt(70);Require(!ResolutionActive(car),"reset retained impact resolution");ArmAngularCcd(car);car.Hold(true);Require(!ResolutionActive(car),"held body retained impact resolution");}finally{UnityEngine.Object.DestroyImmediate(root);}}
  static void Wall(float speed,float angle){var root=new GameObject("physical impact fixture");try{var track=Road(root);var car=Car(root,track,0,75,0,speed);var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.name="Solid impact fixture";wall.transform.SetParent(root.transform);var normal=Quaternion.AngleAxis(angle,car.Frame.normal)*-car.Frame.tangent;
    wall.transform.SetPositionAndRotation(car.Body.position+car.Frame.tangent*12+car.Frame.normal,Quaternion.LookRotation(-normal,car.Frame.normal));wall.transform.localScale=new Vector3(40,8,1);wall.GetComponent<Renderer>().sharedMaterial=track.GetComponentInChildren<MeshRenderer>().sharedMaterial;
    var collider=wall.GetComponent<BoxCollider>();collider.sharedMaterial=new PhysicsMaterial("fixture solid"){staticFriction=0,dynamicFriction=0,bounciness=0};
    int contacts=0;float rebound=0,pointRebound=0,spin=0,maxEnergy=0;Vector3 contactLocal=Vector3.zero;bool hit=false;Vector3 velocityBefore=car.Body.linearVelocity;float initialEnergy=.5f*car.Body.mass*speed*speed;int events=0;var policy=new DrivingContactPolicy();
    car.ContactObserved+=c=>{if(c.collider!=collider)return;contacts++;hit=true;if(c.contactCount>0)contactLocal=Quaternion.Inverse(car.Body.rotation)*(c.GetContact(0).point-car.Body.position);float strength=DrivingContactPolicy.SolidNormalSpeed(c,car.Frame.normal);if(strength>=0&&policy.Solid(0,strength,out _))events++;LogContact(c,car,"wall");};Physics.SyncTransforms();
    for(int tick=0;tick<75;tick++){policy.BeginStep(new[]{new DrivingContactObservation{Id=0,Generation=1,Revision=car.PositionRevision,Normal=car.Frame.normal}});Step(new[]{car},tick,()=>{if(!hit)return;rebound=Mathf.Max(rebound,Vector3.Dot(car.Body.linearVelocity,normal));pointRebound=Mathf.Max(pointRebound,Vector3.Dot(car.Body.GetPointVelocity(car.Body.position+car.Body.rotation*contactLocal),normal));spin=Mathf.Max(spin,car.Body.angularVelocity.magnitude);var omega=Quaternion.Inverse(car.Body.rotation*car.Body.inertiaTensorRotation)*car.Body.angularVelocity;var inertia=car.Body.inertiaTensor;float rotational=.5f*(inertia.x*omega.x*omega.x+inertia.y*omega.y*omega.y+inertia.z*omega.z*omega.z);maxEnergy=Mathf.Max(maxEnergy,.5f*car.Body.mass*car.Body.linearVelocity.sqrMagnitude+rotational);});}
    Log($"WALL speed={speed:F3} angle={angle} contacts={contacts} rebound={rebound:F4} pointRebound={pointRebound:F4} events={events} spin={spin:F4} kineticRatio={maxEnergy/initialEnergy:F5}");Require(contacts>0,"wall fixture missed");Require(events>=1&&events<=3,"solid impact missing or spammed during .75s, events="+events);Require(pointRebound>speed*Mathf.Cos(angle*Mathf.Deg2Rad)*.08f&&rebound>0,"solid impact lacks physical contact-point rebound");Require(maxEnergy<=initialEnergy*1.02f,"impact added kinetic energy without throttle");
   }finally{UnityEngine.Object.DestroyImmediate(root);}}
  static void Escape(float side){var root=new GameObject("physical escape fixture");try{var track=Road(root);var lead=Car(root,track,1,84.25f,0,42);var rear=Car(root,track,0,80,0,44);var cars=new[]{rear,lead};int hits=0;rear.ContactObserved+=c=>{if(c.rigidbody==lead.Body)hits++;};rear.SetInput(new DrivingInput{throttle=1});lead.SetInput(new DrivingInput{throttle=.5f});Physics.SyncTransforms();for(int t=0;t<100;t++)Step(cars,t);
   int before=hits;float time=-1,peakLeader=Vector3.Dot(lead.Body.linearVelocity,lead.Frame.tangent);for(int t=0;t<100;t++){rear.SetInput(new DrivingInput{throttle=1,steer=side*.7f});Step(cars,t+100);peakLeader=Mathf.Max(peakLeader,Vector3.Dot(lead.Body.linearVelocity,lead.Frame.tangent));if(Mathf.Abs(Vector3.Dot(rear.Body.position-lead.Body.position,rear.Frame.right))>VehicleGeometry.Width+.05f){time=(t+1)*.01f;break;}}
   Log($"ESCAPE side={side} initialHits={before} clearanceSeconds={time:F3} leaderSpeed={peakLeader:F3}");Require(before>0,"escape lacked initial contact");Require(time>0&&time<=1,"rear contact cannot escape to free lane in1s");Require(!rear.IsGhosting&&!rear.IsFalling,"escape used recovery");
  }finally{UnityEngine.Object.DestroyImmediate(root);}}
  static void Ramp(float side,float angle,float speed,bool impactCcd=false){var root=new GameObject("physical partial ramp");try{var definition=RoadVolumeChecks.FlatRoad();definition.jumps=new[]{new Procedural.Jump{id="partial",kind="optional",rampStartIndex=12,launchIndex=18,gapStartIndex=19,gapEndIndex=23,landingEndIndex=37,ballisticLandingEndIndex=60,lateralCenter=side*5.333333,lateralHalfWidth=2.666667}};
   var go=new GameObject("ramp road");go.transform.SetParent(root.transform);var track=go.AddComponent<TrackBuilder>();track.Build(new TrackRoute(definition));float lane=-side*2.5f;var car=Car(root,track,0,86,lane,speed,side*-angle);car.SetInput(new DrivingInput{throttle=1});if(impactCcd)ArmAngularCcd(car);int contacts=0,wallContacts=0;float minForward=999,peakHeight=0;bool crossedOpenEdge=false;car.ContactObserved+=c=>{contacts++;for(int i=0;i<c.contactCount;i++)if(Mathf.Abs(Vector3.Dot(c.GetContact(i).normal,car.Frame.normal))<.5f){wallContacts++;LogContact(c,car,"ramp");}};Physics.SyncTransforms();
   for(int t=0;t<65;t++){Step(new[]{car},t);if(car.Distance<120)minForward=Mathf.Min(minForward,Vector3.Dot(car.Body.linearVelocity,car.Frame.tangent));peakHeight=Mathf.Max(peakHeight,Vector3.Dot(car.Body.position-car.Frame.position,car.Frame.normal));crossedOpenEdge|=Mathf.Abs(Vector3.Dot(car.Body.position-car.Frame.position,car.Frame.right))>car.Frame.halfWidth+VehicleGeometry.HalfWidth;}
   Log($"RAMP side={side} angle={angle} impactCcd={impactCcd} speed={speed} contacts={contacts} lateralContacts={wallContacts} minForward={minForward:F4} height={peakHeight:F4}");Require(minForward>12,"partial ramp produced abrupt forward stop");Require(!car.IsFalling||crossedOpenEdge||car.Distance>=120,"partial ramp approach fell while inside road");
  }finally{UnityEngine.Object.DestroyImmediate(root);}}
  static void RampSide(float side){var root=new GameObject("real ramp side impact");try{var definition=RoadVolumeChecks.FlatRoad();definition.jumps=new[]{new Procedural.Jump{id="partial-side",kind="optional",rampStartIndex=12,launchIndex=18,gapStartIndex=19,gapEndIndex=23,landingEndIndex=37,ballisticLandingEndIndex=60,lateralCenter=side*5.333333,lateralHalfWidth=2.666667}};
   var go=new GameObject("ramp side road");go.transform.SetParent(root.transform);var track=go.AddComponent<TrackBuilder>();track.Build(new TrackRoute(definition));var car=Car(root,track,0,113,0,42,-side*90);var outward=car.Frame.right*side;float rebound=0;int hits=0;car.ContactObserved+=c=>{if(DrivingContactPolicy.SolidNormalSpeed(c,car.Frame.normal)>1)hits++;};Physics.SyncTransforms();for(int tick=0;tick<40;tick++)Step(new[]{car},tick,()=>rebound=Mathf.Max(rebound,Vector3.Dot(car.Body.linearVelocity,outward)));
   Log($"REAL_RAMP_SIDE side={side} hits={hits} rebound={rebound:F4}");Require(hits>0&&rebound>3,"real raised ramp side lost physical collision/rebound");
  }finally{UnityEngine.Object.DestroyImmediate(root);}}
  static void CompoundGhost(){var root=new GameObject("compound ghost ownership");try{var track=Road(root);var a=Car(root,track,0,70,0,0);var b=Car(root,track,1,80,0,0);a.Recovery.Observe(.01f,true,0,false,false,true,0,0,0);a.Recovery.Respawn();typeof(MagneticVehicle).GetMethod("BeginGhosting",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(a,null);
   foreach(var x in a.ContactColliders)foreach(var y in b.ContactColliders)Require(Physics.GetIgnoreCollision(x,y),"ghost leaked compound car pair");
   a.Recovery.StepGhost(2);typeof(MagneticVehicle).GetMethod("RestoreCarCollisions",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(a,null);foreach(var x in a.ContactColliders)foreach(var y in b.ContactColliders)Require(!Physics.GetIgnoreCollision(x,y),"compound pair stayed ignored after ghost expiry");
  }finally{UnityEngine.Object.DestroyImmediate(root);}}
  static void SolidPolicy(){var policy=new DrivingContactPolicy();var seen=new[]{new DrivingContactObservation{Id=0,Generation=1,Revision=1,Normal=Vector3.up}};policy.BeginStep(seen);Require(policy.Solid(0,20,out var first)&&first.Strength>.5f,"solid impact strength");for(int i=0;i<100;i++){policy.BeginStep(seen);Require(!policy.Solid(0,20,out _),"continuous multi-face scrape spammed impact");}for(int i=0;i<26;i++)policy.BeginStep(seen);Require(policy.Solid(0,20,out _),"separated impact did not rearm");seen[0].Revision=2;policy.BeginStep(seen);Require(policy.Solid(0,20,out _),"new revision retained old episode");policy.Reset();seen[0].Suppressed=true;policy.BeginStep(seen);Require(policy.Solid(0,20,out _),"real solid collision suppressed by road/flight state");policy.Reset();seen[0].SolidSuppressed=true;policy.BeginStep(seen);Require(!policy.Solid(0,20,out _),"ghost/countdown/finished solid audio leaked");policy.Reset();}
  static void VisualProof(){var root=new GameObject("physical contact preview");try{var track=Road(root);var car=Car(root,track,0,75,0,0);car.ResetPresentation();
   var light=new GameObject("preview light");light.transform.SetParent(root.transform);var sun=light.AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2;light.transform.rotation=Quaternion.Euler(45,-35,0);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.5f,.55f,.65f);
   var cameraObject=new GameObject("preview camera");cameraObject.transform.SetParent(root.transform);var camera=cameraObject.AddComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.045f,.06f,.08f);camera.fieldOfView=42;
   camera.transform.position=car.Body.position+car.Frame.right*5+car.Frame.normal*4-car.Frame.tangent*6;camera.transform.LookAt(car.Body.position+car.Frame.normal*.2f);
   var material=new Material(Shader.Find("Universal Render Pipeline/Unlit"));material.SetColor("_BaseColor",Color.green);
   try{foreach(var box in car.ContactColliders){var go=new GameObject("visible contact section");go.transform.SetParent(car.transform,false);var line=go.AddComponent<LineRenderer>();line.sharedMaterial=material;line.useWorldSpace=false;line.startWidth=line.endWidth=.012f;var b=new Bounds(box.center,box.size);var corners=new Vector3[8];for(int i=0;i<8;i++)corners[i]=b.center+Vector3.Scale(b.extents,new Vector3((i&1)==0?-1:1,(i&2)==0?-1:1,(i&4)==0?-1:1));int[] order={0,1,3,2,0,4,5,1,5,7,3,7,6,2,6,4};line.positionCount=order.Length;line.SetPositions(order.Select(i=>corners[i]).ToArray());}Capture(camera,"collision-envelope.png");}
   finally{UnityEngine.Object.DestroyImmediate(material);}
   UnityEngine.Object.DestroyImmediate(car.gameObject);var definition=RoadVolumeChecks.FlatRoad();definition.jumps=new[]{new Procedural.Jump{id="partial-preview",kind="optional",rampStartIndex=12,launchIndex=18,gapStartIndex=19,gapEndIndex=23,landingEndIndex=37,ballisticLandingEndIndex=60,lateralCenter=5.333333,lateralHalfWidth=2.666667}};track.Build(new TrackRoute(definition));car=Car(root,track,0,86,-2.5f,42);car.SetInput(new DrivingInput{throttle=1});Physics.SyncTransforms();for(int t=0;t<40;t++)Step(new[]{car},t);car.ResetPresentation();camera.transform.position=car.Body.position+car.Frame.right*9+car.Frame.normal*7-car.Frame.tangent*12;camera.transform.LookAt(car.Body.position+car.Frame.tangent*5);Capture(camera,"partial-ramp.png");
  }finally{UnityEngine.Object.DestroyImmediate(root);}}
  static void Capture(Camera camera,string filename){var target=new RenderTexture(1400,900,24);target.Create();var previous=RenderTexture.active;var pixels=new Texture2D(1400,900,TextureFormat.RGB24,false);try{RenderPipeline.SubmitRenderRequest(camera,new UniversalRenderPipeline.SingleCameraRequest{destination=target});RenderTexture.active=target;pixels.ReadPixels(new Rect(0,0,1400,900),0,0);pixels.Apply();var samples=pixels.GetPixels32();int visible=0;foreach(var color in samples)if(color.r>45||color.g>45||color.b>45)visible++;Require(visible>2000,"render capture is blank "+filename);File.WriteAllBytes(Path.Combine(Output,filename),pixels.EncodeToPNG());}finally{RenderTexture.active=previous;target.Release();UnityEngine.Object.DestroyImmediate(target);UnityEngine.Object.DestroyImmediate(pixels);}}
  static void LogContact(Collision c,MagneticVehicle car,string label){if(c.contactCount==0)return;var p=c.GetContact(0);if(Environment.GetEnvironmentVariable("STAR_RACING_PHYSICAL_TRACE")=="1")Log($"CONTACT {label} collider={c.collider.name} point={p.point:F4} normal={p.normal:F4} separation={p.separation:F5} relative={c.relativeVelocity:F4} impulse={c.impulse:F4} carVelocity={car.Body.linearVelocity:F4}");}
 }
}
